//Cost to craft the crate
const CopperCost = 670;
//Amount of copper value equal to amount of resources required to craft the crate
const ResourceCost = 836;
//Amount of copper value equal to amount reagents required to craft the crate
const ReagentCost = 500;
//Amount of Copper per minute at level 10
const CopperPerMinute = 44.807;
//Amount of guild XP per minute at level 10
const GuildXPPerMinute = 1000.40016;
//Rarity Multipler that gets applied to resource cost
const ResourceRarityMult = EvalCurve($#10516612381411114:6064634053840863233$,Float(GetItemRarity()));
//Rarity multiplier that gets applied to reagent cost
const ReagentRarityMult = EvalCurve($#10516612381411114:6064632293965955074$,Float(GetItemRarity()));

(CopperCost + (ResourceCost * ResourceRarityMult) + (ReagentCost * ReagentRarityMult)) / CopperPerMinute * GuildXPPerMinute
